monster_attack <- function(game, monster) {
    say(game, paste0("The ", kind$name, " misses you."))
    return(invisible(NULL))
  }
  say(game, paste0("The ", kind$name, " hits you", if (attack$outcome == "critical") " hard" else "", " for ", attack$damage, "."))
